mapper.select:
SELECT FROM ugc_post p LEFT JOIN sys_user u ON p.user_id = u.id WHERE p.deleted = 0 AND p.status = 1 AND p.is_private = 0
AND p.post_type = #{postType}
ORDER BY p.create_time DESC LIMIT #{offset}, #{size}

mapper.update:
UPDATE ugc_post
SET is_private = #{isPrivate},
    update_time = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0

UPDATE ugc_post
SET deleted = 1,
    update_time = NOW()
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0

